'use strict';

// 模型目录：创作类白名单（图像 + 视频）+ 中转文本白名单。
// 规则：
//   - 创作类（IMAGE/VIDEO）进入 ALLOWED_MODELS，可被 Key 包 allowedModels 授权，
//     供客户创作界面与本地中转（图像/视频端点）使用。
//   - 中转文本（TEXT）是同一批上游 Key 自带能力，默认随 Key 开放给本地中转
//     /v1/chat/completions，不进 Key 包授权字段，避免与创作模型混淆。
// 禁止旧别名与自动扩展：新增模型必须在此显式登记。

const MODELS = Object.freeze({
  // 图像（Image3）
  IMAGE_3: 'qwen-image-3.0',
  IMAGE_3_PRO: 'qwen-image-3.0-pro',
  // 视频（DashScope 统一 video-synthesis 端点）
  WAN3_VIDEO: 'wan3.0-video',
  WAN3_VIDEO_PRIME: 'wan3.0-video-prime',
  HH_1_0_I2V: 'happyhorse-1.0-i2v',
  HH_1_1_I2V: 'happyhorse-1.1-i2v',
  HH_1_1_R2V: 'happyhorse-1.1-r2v',
  WAN27_I2V: 'wan2.7-i2v',
  WAN27_R2V: 'wan2.7-r2v'
});

// 中转文本白名单（DashScope compatible-mode；长期别名优先，稳定可复现）。
const TEXT_MODELS = Object.freeze({
  QWEN_PLUS: 'qwen-plus',
  QWEN_MAX: 'qwen-max'
});

const ALLOWED_MODELS = Object.freeze(Object.values(MODELS));
const TEXT_ALLOWED = Object.freeze(Object.values(TEXT_MODELS));

const IMAGE_MODELS = Object.freeze([MODELS.IMAGE_3, MODELS.IMAGE_3_PRO]);
const VIDEO_MODELS = Object.freeze([
  MODELS.WAN3_VIDEO,
  MODELS.WAN3_VIDEO_PRIME,
  MODELS.HH_1_0_I2V,
  MODELS.HH_1_1_I2V,
  MODELS.HH_1_1_R2V,
  MODELS.WAN27_I2V,
  MODELS.WAN27_R2V
]);

function isAllowedModel(model) {
  return typeof model === 'string' && ALLOWED_MODELS.includes(model);
}

function isImageModel(model) {
  return typeof model === 'string' && IMAGE_MODELS.includes(model);
}

function isVideoModel(model) {
  return typeof model === 'string' && VIDEO_MODELS.includes(model);
}

function isTextModel(model) {
  return typeof model === 'string' && TEXT_ALLOWED.includes(model);
}

// 模型能力类型：'image' | 'video' | 'text'；未知返回 null。
function modelTypeOf(model) {
  if (isImageModel(model)) return 'image';
  if (isVideoModel(model)) return 'video';
  if (isTextModel(model)) return 'text';
  return null;
}

module.exports = {
  MODELS,
  TEXT_MODELS,
  ALLOWED_MODELS,
  TEXT_ALLOWED,
  IMAGE_MODELS,
  VIDEO_MODELS,
  isAllowedModel,
  isImageModel,
  isVideoModel,
  isTextModel,
  modelTypeOf
};
